class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(x):
            res = 1
            i = 2
            while i * i <= x:
                count = 0
                while x % i == 0:
                    count += 1
                    x //= i
                if count % 2 == 1:
                    res *= i
                i += 1
            if x > 1:
                res *= x
            return res

        groups = defaultdict(int)
        for num in nums:
            sf = get_square_free(num)
            groups[sf] += num

        return max(groups.values())
