                    for b in 0,1,2:

                        if a != b and a != curr_i_color_prev and b != prev_j_color_prev:

                            new_cost = prev_dp[prev_j_color_prev][curr_i_color_prev][curr_j_color_prev] + cost[i][a] + cost[j][b]

                            current_dp[curr_j_color_prev][a][b] = min(current_dp[curr_j_color_prev][a][b], new_cost)

prev_dp = current_dp
